import React, { useState } from "react";
import {
  Box, Typography, Button, TextField, Grid, Paper,
  Avatar, Chip, Divider, Stack, Snackbar,
} from "@mui/material";
import { Link } from "react-router-dom";
import simulations from "./Simulations";
import mentors from "./Mentors";
import resources from "./ResourceLibrary";
import { ZB_COLORS } from "./theme";

const events = [
  { title: "Hackathon 2025", date: "June 20, 2025", description: "Showcase your skills at our annual hackathon.", link: "https://example.com/hackathon" },
  { title: "Leadership Webinar", date: "July 15, 2025", description: "Learn leadership skills from industry experts.", link: "https://example.com/webinar" },
];

const StatCard = ({ label, value, accent }) => (
  <Box sx={{
    background: ZB_COLORS.cardBg,
    border: `0.5px solid ${ZB_COLORS.border}`,
    borderRadius: "12px",
    p: 2.5, textAlign: "center",
  }}>
    <Typography sx={{ fontFamily: "Sora", fontWeight: 700, fontSize: "1.75rem", color: accent || ZB_COLORS.gold }}>{value}</Typography>
    <Typography sx={{ fontSize: "0.78rem", color: ZB_COLORS.textMuted, textTransform: "uppercase", letterSpacing: "0.06em", fontFamily: "DM Sans", mt: 0.25 }}>{label}</Typography>
  </Box>
);

const SectionCard = ({ title, children }) => (
  <Box sx={{
    background: ZB_COLORS.navyMid,
    border: `0.5px solid ${ZB_COLORS.border}`,
    borderRadius: "12px",
    p: 3, mb: 2,
  }}>
    <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "1rem", mb: 2 }}>{title}</Typography>
    {children}
  </Box>
);

export default function StudentDashboard({ profile }) {
  const [completed, setCompleted] = useState([]);
  const [reflection, setReflection] = useState("");
  const [reflections, setReflections] = useState([]);
  const [posts, setPosts] = useState([
    { user: "Jane Banda", text: "The Fintech simulation is really eye-opening!", timestamp: new Date() },
  ]);
  const [message, setMessage] = useState("");
  const [snack, setSnack] = useState(false);

  const progress = simulations.length === 0 ? 0 : Math.round((completed.length / simulations.length) * 100);
  const recommended = simulations.filter(s => !completed.some(c => c.id === s.id)).slice(0, 3);

  const handlePost = () => {
    if (!message.trim()) return;
    setPosts([...posts, { user: profile?.name || "You", text: message, timestamp: new Date() }]);
    setMessage("");
  };

  const handleReflection = () => {
    if (!reflection.trim()) return;
    setReflections([{ text: reflection, timestamp: new Date() }, ...reflections]);
    setReflection("");
    setSnack(true);
  };

  return (
    <Box sx={{ maxWidth: 1100, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 6 } }}>
      {/* Header */}
      <Box sx={{
        background: "linear-gradient(135deg, rgba(26,35,126,0.4) 0%, rgba(13,19,42,0) 100%)",
        border: `0.5px solid ${ZB_COLORS.border}`,
        borderRadius: "16px",
        p: { xs: 2.5, md: 4 }, mb: 4,
        display: "flex", alignItems: "center", gap: 3, flexWrap: "wrap",
      }}>
        <Avatar
          src={profile?.avatarUrl}
          sx={{ width: 64, height: 64, background: ZB_COLORS.blue, fontSize: "1.5rem", fontWeight: 700, border: `2px solid ${ZB_COLORS.gold}` }}
        >
          {profile?.name?.[0] || "S"}
        </Avatar>
        <Box sx={{ flexGrow: 1 }}>
          <Typography variant="h4" sx={{ color: "#fff", fontSize: { xs: "1.4rem", md: "1.8rem" } }}>
            Welcome back, {profile?.name || "Student"}
          </Typography>
          <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mt: 0.25 }}>
            {profile?.profession || "Build real skills. Open real doors."}
          </Typography>
        </Box>
        <Button component={Link} to="/simulations" variant="contained" sx={{ whiteSpace: "nowrap" }}>
          Browse simulations
        </Button>
      </Box>

      {/* Stats */}
      <Grid container spacing={1.5} sx={{ mb: 4 }}>
        <Grid item xs={6} sm={3}><StatCard label="Completed" value={completed.length} /></Grid>
        <Grid item xs={6} sm={3}><StatCard label="Available" value={simulations.length} accent="rgba(255,255,255,0.8)" /></Grid>
        <Grid item xs={6} sm={3}><StatCard label="Progress" value={`${progress}%`} /></Grid>
        <Grid item xs={6} sm={3}><StatCard label="Reflections" value={reflections.length} accent="#4caf50" /></Grid>
      </Grid>

      <Grid container spacing={2}>
        <Grid item xs={12} md={8}>
          {/* Progress bar */}
          <SectionCard title="Your progress">
            <Box sx={{ display: "flex", justifyContent: "space-between", mb: 1 }}>
              <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>{completed.length} of {simulations.length} simulations</Typography>
              <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.gold, fontFamily: "DM Sans", fontWeight: 600 }}>{progress}%</Typography>
            </Box>
            <Box sx={{ height: 8, background: ZB_COLORS.border, borderRadius: 4, overflow: "hidden" }}>
              <Box sx={{ width: `${progress}%`, height: "100%", background: ZB_COLORS.gold, borderRadius: 4, transition: "width 0.5s ease" }} />
            </Box>
          </SectionCard>

          {/* Recommended */}
          <SectionCard title="Recommended for you">
            {recommended.length === 0 ? (
              <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>You've completed all available simulations. 🎉</Typography>
            ) : (
              <Grid container spacing={1.5}>
                {recommended.map(sim => (
                  <Grid item xs={12} sm={6} md={4} key={sim.id}>
                    <Box sx={{
                      background: ZB_COLORS.cardBg, border: `0.5px solid ${ZB_COLORS.border}`,
                      borderRadius: "10px", p: 2,
                    }}>
                      <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "0.875rem", mb: 0.75 }}>{sim.title}</Typography>
                      <Typography sx={{ fontSize: "0.78rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 1.5 }}>{sim.description.slice(0, 60)}…</Typography>
                      <Button component={Link} to={`/Simulation/${sim.id}`} variant="contained" size="small" fullWidth sx={{ fontSize: "0.78rem" }}>Start</Button>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            )}
          </SectionCard>

          {/* Community */}
          <SectionCard title="Community forum">
            <Box sx={{ maxHeight: 200, overflowY: "auto", mb: 2 }}>
              {posts.map((p, i) => (
                <Box key={i} sx={{ mb: 1.5 }}>
                  <Typography sx={{ fontSize: "0.75rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>{p.user} · {p.timestamp.toLocaleTimeString()}</Typography>
                  <Typography sx={{ color: "rgba(255,255,255,0.85)", fontFamily: "DM Sans", fontSize: "0.875rem" }}>{p.text}</Typography>
                  <Divider sx={{ borderColor: ZB_COLORS.border, mt: 1 }} />
                </Box>
              ))}
            </Box>
            <Stack direction="row" spacing={1}>
              <TextField placeholder="Share a thought…" value={message} onChange={e => setMessage(e.target.value)} fullWidth size="small" />
              <Button variant="contained" onClick={handlePost} disabled={!message.trim()} sx={{ whiteSpace: "nowrap" }}>Post</Button>
            </Stack>
          </SectionCard>

          {/* Reflection */}
          <SectionCard title="Reflection & feedback">
            <Typography sx={{ fontSize: "0.875rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 2 }}>
              What did you learn from your last simulation? What would you do differently?
            </Typography>
            <TextField label="Write your reflection" multiline minRows={3} fullWidth value={reflection} onChange={e => setReflection(e.target.value)} sx={{ mb: 2 }} />
            <Button variant="contained" onClick={handleReflection} disabled={!reflection.trim()}>Submit reflection</Button>
            {reflections.length > 0 && (
              <Box sx={{ mt: 3 }}>
                {reflections.map((r, i) => (
                  <Box key={i} sx={{ background: ZB_COLORS.cardBg, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "8px", p: 2, mb: 1.5 }}>
                    <Typography sx={{ fontSize: "0.75rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 0.5 }}>{r.timestamp.toLocaleString()}</Typography>
                    <Typography sx={{ color: "rgba(255,255,255,0.8)", fontFamily: "DM Sans", fontSize: "0.875rem" }}>{r.text}</Typography>
                  </Box>
                ))}
              </Box>
            )}
          </SectionCard>
        </Grid>

        {/* Sidebar */}
        <Grid item xs={12} md={4}>
          <SectionCard title="Resources for you">
            {resources.length === 0 ? (
              <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>No resources yet.</Typography>
            ) : (
              resources.map((res, i) => (
                <Box key={i} sx={{ mb: 2 }}>
                  <Box component="a" href={res.url} target="_blank" rel="noopener noreferrer" sx={{ color: ZB_COLORS.gold, fontSize: "0.875rem", fontFamily: "DM Sans", textDecoration: "none", "&:hover": { textDecoration: "underline" } }}>
                    {res.title}
                  </Box>
                  <Typography sx={{ fontSize: "0.75rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>{res.type}</Typography>
                </Box>
              ))
            )}
          </SectionCard>

          <SectionCard title="Mentors">
            {mentors.length === 0 ? (
              <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>No mentors available yet.</Typography>
            ) : (
              mentors.map((m, i) => (
                <Box key={i} sx={{ mb: 2 }}>
                  <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "0.9rem" }}>{m.name}</Typography>
                  <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 0.75 }}>{m.bio}</Typography>
                  <Button href={`mailto:${m.email}`} size="small" sx={{ color: ZB_COLORS.gold, fontSize: "0.78rem", p: 0 }}>Request feedback →</Button>
                  {i < mentors.length - 1 && <Divider sx={{ borderColor: ZB_COLORS.border, mt: 1.5 }} />}
                </Box>
              ))
            )}
          </SectionCard>

          <SectionCard title="Upcoming events">
            {events.map((ev, i) => (
              <Box key={i} sx={{ mb: 2 }}>
                <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "0.875rem" }}>{ev.title}</Typography>
                <Chip label={ev.date} size="small" sx={{ background: "rgba(255,214,0,0.1)", color: ZB_COLORS.gold, border: `0.5px solid rgba(255,214,0,0.3)`, fontFamily: "DM Sans", fontSize: "0.7rem", my: 0.75 }} />
                <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 0.5 }}>{ev.description}</Typography>
                <Button href={ev.link} target="_blank" size="small" sx={{ color: ZB_COLORS.gold, fontSize: "0.78rem", p: 0 }}>Learn more →</Button>
                {i < events.length - 1 && <Divider sx={{ borderColor: ZB_COLORS.border, mt: 1.5 }} />}
              </Box>
            ))}
          </SectionCard>
        </Grid>
      </Grid>

      <Snackbar open={snack} autoHideDuration={3000} onClose={() => setSnack(false)} message="Reflection saved!" />
    </Box>
  );
}
